function debounceAdvanced(fn, delay, options = {}) {
  const { leading = false, trailing = true } = options;
  let timerId = null;
  let lastArgs = null;
  let lastThis = null;

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const shouldCallLeading = leading && !timerId;

    if (timerId !== null) {
      clearTimeout(timerId);
    }

    if (shouldCallLeading) {
      fn.apply(lastThis, lastArgs);
      lastArgs = null;
      lastThis = null;
    }

    timerId = setTimeout(() => {
      if (trailing && lastArgs) {
        fn.apply(lastThis, lastArgs);
      }
      timerId = null;
      lastArgs = null;
      lastThis = null;
    }, delay);
  }

  debounced.cancel = function() {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    lastArgs = null;
    lastThis = null;
  };

  debounced.flush = function() {
    if (timerId !== null && lastArgs) {
      fn.apply(lastThis, lastArgs);
      debounced.cancel();
    }
  };

  return debounced;
}
